PRAGMA foreign_keys = ON;
CREATE TABLE rol (id INTEGER PRIMARY KEY AUTOINCREMENT, nombre TEXT NOT NULL UNIQUE, descripcion TEXT);
CREATE TABLE usuario (id INTEGER PRIMARY KEY AUTOINCREMENT, nombre TEXT NOT NULL, email TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, rol_id INTEGER NOT NULL, activo INTEGER NOT NULL DEFAULT 1, creado_en TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (rol_id) REFERENCES rol(id));
CREATE TABLE cliente_responsable (id INTEGER PRIMARY KEY AUTOINCREMENT, dni TEXT NOT NULL UNIQUE, nombre TEXT NOT NULL, apellidos TEXT NOT NULL, telefono TEXT, email TEXT, direccion TEXT, creado_en TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE fallecido (id INTEGER PRIMARY KEY AUTOINCREMENT, dni TEXT UNIQUE, nombre TEXT NOT NULL, apellidos TEXT NOT NULL, fecha_defuncion TEXT, lugar_defuncion TEXT, creado_en TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE expediente (id INTEGER PRIMARY KEY AUTOINCREMENT, codigo TEXT NOT NULL UNIQUE, cliente_id INTEGER NOT NULL, fallecido_id INTEGER NOT NULL, fecha_apertura TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, estado TEXT NOT NULL DEFAULT 'abierto', FOREIGN KEY (cliente_id) REFERENCES cliente_responsable(id), FOREIGN KEY (fallecido_id) REFERENCES fallecido(id));
CREATE TABLE estado_orden (id INTEGER PRIMARY KEY AUTOINCREMENT, nombre TEXT NOT NULL UNIQUE, descripcion TEXT, orden_logico INTEGER NOT NULL);
CREATE TABLE orden_funeraria (id INTEGER PRIMARY KEY AUTOINCREMENT, expediente_id INTEGER NOT NULL, tipo_servicio TEXT NOT NULL CHECK(tipo_servicio IN ('incineracion','inhumacion')), estado_id INTEGER NOT NULL, total_estimado REAL NOT NULL DEFAULT 0, observacion_general TEXT, fecha_creacion TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, fecha_actualizacion TEXT, FOREIGN KEY (expediente_id) REFERENCES expediente(id), FOREIGN KEY (estado_id) REFERENCES estado_orden(id));
CREATE TABLE categoria_producto (id INTEGER PRIMARY KEY AUTOINCREMENT, nombre TEXT NOT NULL UNIQUE, descripcion TEXT);
CREATE TABLE producto (id INTEGER PRIMARY KEY AUTOINCREMENT, categoria_id INTEGER NOT NULL, nombre TEXT NOT NULL, descripcion TEXT, precio_base REAL NOT NULL, activo INTEGER NOT NULL DEFAULT 1, FOREIGN KEY (categoria_id) REFERENCES categoria_producto(id));
CREATE TABLE detalle_orden (id INTEGER PRIMARY KEY AUTOINCREMENT, orden_id INTEGER NOT NULL, producto_id INTEGER, concepto TEXT NOT NULL, cantidad INTEGER NOT NULL DEFAULT 1, precio_unitario REAL NOT NULL, subtotal REAL NOT NULL, creado_en TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (orden_id) REFERENCES orden_funeraria(id) ON DELETE CASCADE, FOREIGN KEY (producto_id) REFERENCES producto(id));
CREATE TABLE servicio_complementario (id INTEGER PRIMARY KEY AUTOINCREMENT, nombre TEXT NOT NULL UNIQUE, descripcion TEXT, precio_base REAL NOT NULL, activo INTEGER NOT NULL DEFAULT 1);
CREATE TABLE orden_servicio_complementario (orden_id INTEGER NOT NULL, servicio_id INTEGER NOT NULL, precio_aplicado REAL NOT NULL, creado_en TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (orden_id, servicio_id), FOREIGN KEY (orden_id) REFERENCES orden_funeraria(id) ON DELETE CASCADE, FOREIGN KEY (servicio_id) REFERENCES servicio_complementario(id));
CREATE TABLE observacion (id INTEGER PRIMARY KEY AUTOINCREMENT, orden_id INTEGER NOT NULL, usuario_id INTEGER NOT NULL, texto TEXT NOT NULL, fecha_creacion TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (orden_id) REFERENCES orden_funeraria(id) ON DELETE CASCADE, FOREIGN KEY (usuario_id) REFERENCES usuario(id));
CREATE TABLE auditoria (id INTEGER PRIMARY KEY AUTOINCREMENT, usuario_id INTEGER, entidad TEXT NOT NULL, entidad_id INTEGER NOT NULL, accion TEXT NOT NULL, fecha TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, detalle TEXT, FOREIGN KEY (usuario_id) REFERENCES usuario(id));
